1	export type ModelId = "katara" | "sokka" | "yako";
2	
3	export type CategoryKey =
4	  | "weapons"
5	  | "creatures"
6	  | "worlds"
7	  | "mechanics"
8	  | "shaders"
9	  | "magic"
10	  | "quests"
11	  | "interface"
12	  | "audio"
13	  | "vehicles"
14	  | "items"
15	  | "characters";
16	
17	export type GameId = "minecraft" | "skyrim" | "stardew" | "terraria" | "cyberpunk";
18	
19	export type EmblemKey = "cube" | "dragon" | "sprout" | "tree" | "chip";
20	
21	export interface Game {
22	  id: GameId;
23	  name: string;
24	  /** Short label used where space is tight. */
25	  short: string;
26	  /** Mod toolchain, e.g. "Fabric · Java 21". */
27	  toolchain: string;
28	  language: CodeLanguage;
29	  /** Neon accent used for the branch, as an "r g b" triple. */
30	  rgb: string;
31	  emblem: EmblemKey;
32	  blurb: string;
33	  aliases: string[];
34	  categories: CategoryKey[];
35	}
36	
37	export interface CategoryMeta {
38	  key: CategoryKey;
39	  label: string;
40	  rgb: string;
41	  description: string;
42	  keywords: string[];
43	}
44	
45	export type CodeLanguage = "java" | "papyrus" | "csharp" | "lua" | "glsl" | "json" | "markdown" | "xml" | "toml" | "text";
46	
47	export interface ModFile {
48	  path: string;
49	  language: CodeLanguage;
50	  content: string;
51	}
52	
53	export interface ModVersion {
54	  id: string;
55	  label: string;
56	  createdAt: number;
57	  model: ModelId;
58	  credits: number;
59	  prompt: string;
60	  summary: string;
61	  files: ModFile[];
62	  additions: number;
63	  deletions: number;
64	}
65	
66	export interface Mod {
67	  id: string;
68	  gameId: GameId;
69	  category: CategoryKey;
70	  name: string;
71	  summary: string;
72	  createdAt: number;
73	  tags: string[];
74	  /** Seed mods have their files built lazily from the engine templates. */
75	  seed?: boolean;
76	  versions: ModVersion[];
77	  activeVersionId?: string;
78	}
79	
80	export interface ModelMeta {
81	  id: ModelId;
82	  name: string;
83	  credits: number;
84	  tagline: string;
85	  description: string;
86	  rgb: string;
87	  /** Visual pacing for the simulated stream. */
88	  chunk: [number, number];
89	  tick: number;
90	}
91	
92	export type Level = "core" | "game" | "category" | "mod";
93	
94	export interface Selection {
95	  level: Level;
96	  gameId?: GameId;
97	  category?: CategoryKey;
98	  modId?: string;
99	}
100	
101	/** Events streamed from /api/generate as NDJSON lines. */
102	export type GenEvent =
103	  | { type: "start"; jobId: string; model: ModelId; credits: number }
104	  | { type: "route"; gameId: GameId; category: CategoryKey; modName: string; modId: string; summary: string; tags: string[] }
105	  | { type: "think"; id: string; label: string; detail?: string }
106	  | { type: "think-done"; id: string }
107	  | { type: "file"; path: string; language: CodeLanguage }
108	  | { type: "chunk"; path: string; text: string }
109	  | { type: "file-done"; path: string }
110	  | { type: "done"; summary: string; notes: string }
111	  | { type: "error"; message: string };
