const f = (n) => +n.toFixed(2);
function gear(cx, cy, ro, ri, n, phaseDeg) {
  // fractions of one tooth period: valley, rise, top, fall
  const P = (2 * Math.PI) / n;
  const ph = (phaseDeg * Math.PI) / 180;
  const pt = (r, a) => [f(cx + r * Math.cos(a)), f(cy + r * Math.sin(a))];
  let d = "";
  for (let i = 0; i < n; i++) {
    const a0 = ph + i * P;
    const v0 = a0, v1 = a0 + P * 0.4;      // valley arc on root
    const t0 = a0 + P * 0.52, t1 = a0 + P * 0.88; // top arc
    const [x0, y0] = pt(ri, v0), [x1, y1] = pt(ri, v1), [x2, y2] = pt(ro, t0), [x3, y3] = pt(ro, t1);
    d += (i === 0 ? `M${x0} ${y0}` : `L${x0} ${y0}`) + `A${ri} ${ri} 0 0 1 ${x1} ${y1}L${x2} ${y2}A${ro} ${ro} 0 0 1 ${x3} ${y3}`;
  }
  return d + "Z";
}
// big gear: center so that small gear meshes along 45deg diagonal
const cb = [9.4, 9.4], cs = [16.1, 16.1];
console.log("dist", Math.hypot(cs[0]-cb[0], cs[1]-cb[1]));
// big: 8 teeth; want a valley centred at 45deg. valley centre = phase + P*0.2 (valley 0..0.4) -> but tooth centre at 0.7P.
// valley spans [0,0.4] plus flanks; valley centre approx (0.94+0.4)/2? treat gap centre = (t1 .. next v1) -> (0.88P + 1.4P)/2 - P = 0.14P... simpler: gap center ~ 0.2P - small; use 0.2P
const Pb = 360/8, Ps = 360/6;
const phB = 45 - 0.2*Pb; // valley centred at 45deg
const phS = 225 - 0.7*Ps; // tooth centred at 225deg (pointing to big gear)
console.log("BIG", gear(cb[0], cb[1], 6.6, 5.0, 8, phB));
console.log("SMALL", gear(cs[0], cs[1], 4.4, 3.2, 6, phS));
EOF
node gen.mjs

