cd "C:/Users/edmem/AppData/Local/Temp/claude/C--Users-edmem-AppData-Roaming-Claude-scratch-workspaces-0a5c5ed9-8987-4824-aeb8-bdf4f706f10c-558b3c22-dbeb-42c0-ac92-8b838fdb343c-scratch-2026-10-07-d9846f/a29cf244-79c9-4ba3-aea9-1b8beb78ecca/scratchpad" && cat > gen2.mjs <<'EOF'
const f = (n) => +n.toFixed(2);
const rad = (d) => (d * Math.PI) / 180;
function ccwArrow(cx, cy, r, aStart, aEnd, wing = 3.4, spread = 42) {
  // arc drawn from B(aEnd) ... we draw from A(aStart) clockwise (sweep 1) to B(aEnd); arrow head at A pointing CCW
  const A = [cx + r * Math.cos(rad(aStart)), cy + r * Math.sin(rad(aStart))];
  const B = [cx + r * Math.cos(rad(aEnd)), cy + r * Math.sin(rad(aEnd))];
  let span = (aEnd - aStart + 360) % 360;
  const large = span > 180 ? 1 : 0;
  const dir = [Math.sin(rad(aStart)), -Math.cos(rad(aStart))]; // ccw tangent
  const back = [-dir[0], -dir[1]];
  const rot = (v, d) => [v[0] * Math.cos(rad(d)) - v[1] * Math.sin(rad(d)), v[0] * Math.sin(rad(d)) + v[1] * Math.cos(rad(d))];
  const w1 = rot(back, spread), w2 = rot(back, -spread);
  const T = [A[0] + dir[0] * 0.3, A[1] + dir[1] * 0.3];
  const arc = `M${f(A[0])} ${f(A[1])}A${r} ${r} 0 ${large} 1 ${f(B[0])} ${f(B[1])}`;
  const head = `M${f(T[0] + w1[0] * wing)} ${f(T[1] + w1[1] * wing)}L${f(T[0])} ${f(T[1])}L${f(T[0] + w2[0] * wing)} ${f(T[1] + w2[1] * wing)}`;
  return { arc, head };
}
console.log("restore", ccwArrow(12, 12.4, 8, 218, 160));
console.log("history", ccwArrow(12, 12.2, 8.6, 214, 160, 3.2));
function edges(c, rc, nodes) {
  return nodes.map(([x, y, r]) => {
    const dx = x - c[0], dy = y - c[1], L = Math.hypot(dx, dy);
    const ux = dx / L, uy = dy / L;
    const g = 0.0;
    return `M${f(c[0] + ux * (rc + g))} ${f(c[1] + uy * (rc + g))}L${f(x - ux * (r + g))} ${f(y - uy * (r + g))}`;
  }).join("");
}
const C = [12, 12.5];
const nodes = [[5.5, 6, 1.9], [18, 4.5, 1.9], [20, 13, 1.9], [15.5, 20, 1.9], [5, 17, 1.9]];
console.log("brain edges", edges(C, 2.8, nodes));
console.log("peripheral", edges([5.5, 6], 1.9, [[5, 17, 1.9]]), edges([18, 4.5], 1.9, [[20, 13, 1.9]]));
EOF
