import type { SVGProps } from "react";

/**
 * Cyrus icon system — shared primitives + generic UI icons.
 *
 * Every icon is a 24×24 stroke drawing in `currentColor`, so it inherits
 * text color (and any neon `drop-shadow` glow) from its parent in both themes.
 * Depth comes from a translucent "duotone" fill on one or two inner shapes.
 */

export type IconProps = SVGProps<SVGSVGElement>;

/** Translucent inner fill used for the duotone accent (no stroke). */
export const DUO = { fill: "currentColor", fillOpacity: 0.2, stroke: "none" } as const;

/** Translucent fill that keeps the shape's outline stroke. */
export const DUO_STROKED = { fill: "currentColor", fillOpacity: 0.2 } as const;

/** Solid fill, no stroke — for tiny sparks, pupils and pads. */
export const SOLID = { fill: "currentColor", stroke: "none" } as const;

/** Path data for a small concave 4-point "spark" star centred on (cx, cy). */
export function sparkPath(cx: number, cy: number, r: number): string {
  const k = r * 0.18;
  return (
    `M${cx} ${cy - r}` +
    `Q${cx + k} ${cy - k} ${cx + r} ${cy}` +
    `Q${cx + k} ${cy + k} ${cx} ${cy + r}` +
    `Q${cx - k} ${cy + k} ${cx - r} ${cy}` +
    `Q${cx - k} ${cy - k} ${cx} ${cy - r}Z`
  );
}

/**
 * Base <svg> wrapper shared by every Cyrus icon. Defaults to `1em` square,
 * decorative (`aria-hidden`) unless a label is supplied; all props override.
 */
export function IconBase({ children, ...props }: IconProps) {
  const labelled = props["aria-label"] != null || props["aria-labelledby"] != null;
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      width="1em"
      height="1em"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.6}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden={labelled ? undefined : true}
      focusable="false"
      {...props}
    >
      {children}
    </svg>
  );
}

/** UI chrome icons run a touch heavier so they stay crisp at 14–16px. */
function UiBase(props: IconProps) {
  return <IconBase strokeWidth={1.7} {...props} />;
}

/* ───────────────────────────── Input & chat ───────────────────────────── */

export function MicIcon(props: IconProps) {
  return (
    <UiBase {...props}>
      <rect x={9} y={3} width={6} height={11} rx={3} {...DUO_STROKED} />
      <path d="M5.5 11a6.5 6.5 0 0 0 13 0M12 17.5V21M9 21h6" />
    </UiBase>
  );
}

export function ImageIcon(props: IconProps) {
  return (
    <UiBase {...props}>
      <rect x={3} y={4} width={18} height={16} rx={2.5} />
      <circle cx={8.5} cy={9.5} r={1.7} />
      <path d="M3.5 17.5 8.8 12.6l3.7 3.4 3.1-2.8 4.9 4.3" />
    </UiBase>
  );
}

export function SendIcon(props: IconProps) {
  return (
    <UiBase {...props}>
      <path d="M12 19.5V4.8M5.8 11 12 4.8l6.2 6.2" />
    </UiBase>
  );
}

export function PaperclipIcon(props: IconProps) {
  return (
    <UiBase {...props}>
      <path
        transform="rotate(45 12 12)"
        d="M16.5 7.5v8a4.5 4.5 0 0 1-9 0V6.5a3 3 0 0 1 6 0V15a1.5 1.5 0 0 1-3 0V8"
      />
    </UiBase>
  );
}

export function CopyIcon(props: IconProps) {
  return (
    <UiBase {...props}>
      <rect x={9} y={9} width={12} height={12} rx={2.2} {...DUO_STROKED} />
      <path d="M15 9V5.2A2.2 2.2 0 0 0 12.8 3H5.2A2.2 2.2 0 0 0 3 5.2v7.6A2.2 2.2 0 0 0 5.2 15H9" />
    </UiBase>
  );
}

export function CheckIcon(props: IconProps) {
  return (
    <UiBase {...props}>
      <path d="m4.5 12.5 5 5 10-11" />
    </UiBase>
  );
}

export function DownloadIcon(props: IconProps) {
  return (
    <UiBase {...props}>
      <path d="M12 3.5V15M7 10l5 5 5-5M4 15.5v3a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-3" />
    </UiBase>
  );
}

export function CloseIcon(props: IconProps) {
  return (
    <UiBase {...props}>
      <path d="M6 6l12 12M18 6 6 18" />
    </UiBase>
  );
}

export function PlusIcon(props: IconProps) {
  return (
    <UiBase {...props}>
      <path d="M12 5v14M5 12h14" />
    </UiBase>
  );
}

export function MinusIcon(props: IconProps) {
  return (
    <UiBase {...props}>
      <path d="M5 12h14" />
    </UiBase>
  );
}

export function SearchIcon(props: IconProps) {
  return (
    <UiBase {...props}>
      <circle cx={10.5} cy={10.5} r={6.5} />
      <path d="m15.4 15.4 5.1 5.1" />
    </UiBase>
  );
}

/* ───────────────────────────── Theme & flair ───────────────────────────── */

export function SunIcon(props: IconProps) {
  return (
    <UiBase {...props}>
      <circle cx={12} cy={12} r={4} {...DUO_STROKED} />
      <path d="M12 2.5v2M12 19.5v2M2.5 12h2M19.5 12h2M5.3 5.3l1.4 1.4M17.3 17.3l1.4 1.4M5.3 18.7l1.4-1.4M17.3 6.7l1.4-1.4" />
    </UiBase>
  );
}

export function MoonIcon(props: IconProps) {
  return (
    <UiBase {...props}>
      <path d="M19.8 14.6A8.2 8.2 0 1 1 9.4 4.2a6.6 6.6 0 0 0 10.4 10.4Z" {...DUO_STROKED} />
    </UiBase>
  );
}

export function SparkleIcon(props: IconProps) {
  return (
