/**
 * Cyrus icon system — shared primitives + generic UI icons.
 *
 * Every icon is a 24×24 stroke drawing in `currentColor`, so it inherits
 * text color (and any neon `drop-shadow` glow) from its parent in both themes.
 * Depth comes from a translucent "duotone" fill on one or two inner shapes.
 */

export type IconProps = SVGProps<SVGSVGElement>;

/** Translucent inner fill used for the duotone accent (no stroke). */
export const DUO = { fill: "currentColor", fillOpacity: 0.2, stroke: "none" } as const;

/** Translucent fill that keeps the shape's outline stroke. */
export const DUO_STROKED = { fill: "currentColor", fillOpacity: 0.2 } as const;

/** Solid fill, no stroke — for tiny sparks, pupils and pads. */
export const SOLID = { fill: "currentColor", stroke: "none" } as const;

/** Path data for a small concave 4-point "spark" star centred on (cx, cy). */
export function sparkPath(cx: number, cy: number, r: number): string {
  const k = r * 0.18;
  return (
    `M${cx} ${cy - r}` +
    `Q${cx + k} ${cy - k} ${cx + r} ${cy}` +
    `Q${cx + k} ${cy + k} ${cx} ${cy + r}` +
    `Q${cx - k} ${cy + k} ${cx - r} ${cy}` +
    `Q${cx - k} ${cy - k} ${cx} ${cy - r}Z`
  );
}

/**
 * Base <svg> wrapper shared by every Cyrus icon. Defaults to `1em` square,
 * decorative (`aria-hidden`) unless a label is supplied; all props override.
 */
export function IconBase({ children, ...props }: IconProps) {
  const labelled = props["aria-label"] != null || props["aria-labelledby"] != null;
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      width="1em"
      height="1em"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.6}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden={labelled ? undefined : true}
      focusable="false"
      {...props}
    >
      {children}
    </svg>
  );
}

