const React = require("react");
const { renderToStaticMarkup } = require("react-dom/server");
const dir = process.argv[2];
const ui = require(dir + "/ui.js"), cat = require(dir + "/CategoryIcons.js"), gem = require(dir + "/GameEmblems.js"), mg = require(dir + "/ModelGlyphs.js");
const sections = [
  ["Categories", Object.entries(cat.CATEGORY_ICONS)],
  ["Emblems", Object.entries(gem.GAME_EMBLEMS)],
  ["Models", Object.entries(mg.MODEL_GLYPHS)],
  ["UI", Object.entries(ui).filter(([k]) => k.endsWith("Icon"))],
];
const sizes = [16, 20, 28, 64];
let html = `<!doctype html><meta charset=utf-8><style>
body{font:12px system-ui;margin:12px;background:#0b0618;color:#c9b6ff}
.light{background:#f4f1fb;color:#3a1d8a}
.row{display:flex;align-items:center;gap:14px;padding:4px 8px;border-bottom:1px solid #ffffff14}
.name{width:110px;opacity:.7}
.orb{display:inline-grid;place-items:center;width:40px;height:40px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#8f5bff,#3a1270);color:#fff;filter:drop-shadow(0 0 6px #a37bff)}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:0}
h2{margin:10px 0 4px;font-size:14px}
</style>`;
for (const theme of ["dark", "light"]) {
  html += `<div class="${theme === "light" ? "light" : ""}" style="padding:6px"><h2>${theme}</h2><div class=grid>`;
  for (const [title, list] of sections) {
    for (const [name, C] of list) {
      html += `<div class=row><span class=name>${name}</span>` + sizes.map(s => renderToStaticMarkup(React.createElement(C, { style: { fontSize: s } }))).join("") +
        `<span class=orb>${renderToStaticMarkup(React.createElement(C, { style: { fontSize: 22 } }))}</span></div>`;
    }
  }
  html += `</div></div>`;
}
require("fs").writeFileSync(process.argv[3], html);
console.log("ok");
EOF
