// usage: node try.cjs candidates.json out.png  — candidates: {name: "<inner svg markup>"}
const sharp = require("sharp");
const [inp, out] = process.argv.slice(2);
const cands = Object.entries(JSON.parse(require("fs").readFileSync(inp, "utf8")));
const wrap = (inner, sz) => `<svg xmlns="http://www.w3.org/2000/svg" width="${sz}" height="${sz}" viewBox="0 0 24 24" fill="none" stroke="#d6c6ff" color="#d6c6ff" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">${inner}</svg>`;
const cw = 330, ch = 200, cols = 4;
(async () => {
  const comps = [];
  for (let i = 0; i < cands.length; i++) {
    const [name, inner] = cands[i];
    const x0 = (i % cols) * cw, y0 = Math.floor(i / cols) * ch;
    comps.push({ input: await sharp(Buffer.from(wrap(inner, 168))).png().toBuffer(), left: x0 + 4, top: y0 + 22 });
    for (const [sz, k, dy] of [[16, 5, 22], [24, 4, 112]]) {
      const buf = await sharp(Buffer.from(`<svg xmlns="http://www.w3.org/2000/svg" width="${sz}" height="${sz}"><rect width="100%" height="100%" fill="#0b0618"/>${wrap(inner, sz)}</svg>`)).png().toBuffer();
      if (sz === 16) comps.push({ input: await sharp(buf).resize(80, 80, { kernel: "nearest" }).png().toBuffer(), left: x0 + 180, top: y0 + dy });
      else comps.push({ input: buf, left: x0 + 200, top: y0 + dy + 20 });
    }
    comps.push({ input: Buffer.from(`<svg xmlns="http://www.w3.org/2000/svg" width="300" height="20"><text x="0" y="14" font-family="Segoe UI" font-size="13" fill="#9a88cc">${name}</text></svg>`), left: x0 + 6, top: y0 + 2 });
  }
  await sharp({ create: { width: cols * cw, height: Math.ceil(cands.length / cols) * ch, channels: 4, background: "#0b0618" } }).composite(comps).png().toFile(out);
  console.log("ok");
})();
EOF
